// Demo retrieval result over the employee handbook.
const q = $input.first().json.query;
const chunks = [
  { text:"Full-time employees accrue 20 days PTO per year, accrued monthly, rolling over up to 5 days.", source:"Handbook §4.2 Paid Time Off", score:0.91 },
  { text:"PTO requests are submitted in the HRIS and approved by your manager.", source:"Handbook §4.3 Requesting Leave", score:0.83 },
  { text:"Public holidays are additional to PTO and follow the regional calendar.", source:"Handbook §4.5 Holidays", score:0.71 }
];
const top = Math.max(...chunks.map(c=>c.score));
return [{ json:{ query:q, chunks, top_score:top, retrieved:chunks.length }}];

// Claude composes a grounded, cited answer from retrieved chunks.
const d=$input.first().json;
const cite=d.chunks.filter(c=>c.score>=0.8).map(c=>c.source);
return [{ json:{
  answer:"You accrue 20 PTO days per year (monthly, up to 5 roll over). Submit requests in the HRIS for manager approval. Public holidays are separate.",
  citations:cite, confidence:d.top_score, grounded:true, channel:d.channel
}}];
